head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screnId = "ULDBNS00100"; // 화면ID(업무공통 SCREN_ID 전달용 — fn_SetMktactCd 에서 프로그램 ID 기준 재설정)
scwin.vMktactCd = "113";
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "1";
scwin.vRowCount = 0;
scwin.processGp = "";
scwin.vProcsStatCd = "";
scwin.vRegYn = 'N';
scwin.vRowPos = 0;
scwin.arrPar = [];
scwin.vSelObj = null; // 발행기관 팝업 결과를 받을 대상 컴포넌트

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description /////// 2. 초기화 영역 /////////
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 세션 사용자 정보 보관, 버튼·항목 숨김, 탭 초기 선택, 콤보·시장조치구분 설정 후 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    // 적용일 설정
    await scwin.searchClsDd('');

    // 숨기기
    lbl_ReturnPos.hide();
    btn_StdCdReq.hide();
    txb_Dtl1.hide();
    btn_Search2.hide();
    btn_ApprovFileCreat.hide();
    btn_ProcsComplt.hide();
    btn_Update.hide();
    btn_TeamleadrConfrm.hide();
    btn_AcptRet.hide();

    // 상장일숨기기
    label_103.hide(); // 상장일달력
    edt_ListDd.hide(); // 상장일달력
    txb_FrnBasIntTpCd2.hide();

    scwin.chgStatComp();

    // 탭지정
    tab_List.setSelectedTabIndex(0);
    tab_Detail.setSelectedTabIndex(0);
    tab_SecutizAsst.setSelectedTabIndex(0);

    // 콤보설정
    // scwin.setComboCode();

    // 시장조치구분 설정
    scwin.setMktactCd();

    // 탭설정
    // scwin.setDtlTab();

    // 목록조회
    await scwin.listSync();

    // 임시데이터셋설정
    // dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    // dts_Temp.insertRow();

    // 적용일 셋팅
    // vStrtDd = dma_checkCls.NameValue(1, 'CLS_DD');

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dlt_bndOptionCall_onrowpositionchange
 * @description /////// 3. 컴포넌트 이벤트 영역 /////////
 * @param {Object} info info
 * @returns {void}
 * @hidden N
 */
scwin.dlt_bndOptionCall_onrowpositionchange = function (info) {
    try {
        let row = info.newRowIndex;
        if (row > -1) {
            if (dlt_bndOptionCall.getCellData(row, 'callExerStrtDd') !== '' && dlt_bndOptionCall.getCellData(row, 'callExerEndDd') !== '') {
                scwin.chkCall();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS00100.dlt_bndOptionCall_onrowpositionchange" });
    }
};

/**
 * @method
 * @name dlt_bndOptionPut_onrowpositionchange
 * @description 풋옵션 목록 행 위치 변경 — 선택 행 기준 화면 반영
 * @param {Object} info info
 * @returns {void}
 * @hidden N
 */
scwin.dlt_bndOptionPut_onrowpositionchange = function (info) {
    try {
        let row = info.newRowIndex;
        if (row > -1) {
            if (dlt_bndOptionPut.getCellData(row, 'putExerStrtDd') !== '' && dlt_bndOptionPut.getCellData(row, 'putExerEndDd') !== '') {
                scwin.chkPut();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS00100.dlt_bndOptionPut_onrowpositionchange" });
    }
};

/**
 * @method
 * @name img_BndTpNm_onclick
 * @description img_BndTpNm 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_BndTpNm_onclick = async function () {
    try {
        scwin.getBndClss();
        const url = "/ui/bns/bnscommon/ULDBNS90002.xml";
        const options = {
            id: "ULDBNS90002",
            popupName: "채권분류코드 검색",
            frameModal: "top",
            width: 600,
            height: 500,
        };
        const rtn = await $c.win.openPopup(url, options, scwin.arrPar);
        scwin.setBndClss(rtn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.img_BndTpNm_onclick" });
    }
};

