/**
 * @method
 * @name btn_AttachDoc_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_AttachDoc_onclick = async function () {
    try {
        if (scwin.vRowCount === 0) return;

        if (await $c.bns.hasAttachDoc(scwin.screnId, dma_bndattachDocYnEnd, scwin.vBndApplId, scwin.vBndListProcsTpCd) > 0) return;

        scwin.getCommonKey();
        await $c.bns.popAttachDocSearch(scwin.arrPar);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.btn_AttachDoc_onclick" });
    }
};

