/**
 * @method
 * @name btn_StdCdReq_onclick
 * @description 「표준코드요청」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_StdCdReq_onclick = async function () {
    try {
        if (scwin.vRowCount === 0) return;
        scwin.processGp = '9';
        // 전자단기사채이면 표준코드 저장테이블이 다름.
        if (cmb_NusualBndTpCd.getValue() === '5') {
            await $c.bns.processStdCdReq1(scwin.vBndApplId); // TODO Stage2: pcc bns_common.processStdCdReq1 시그니처(bndApplId) 기준 — 업무공통 전환 후 재대조
            return;
        }
        $c.bns.processStdCdReq(scwin.vBndApplId); // TODO Stage2: pcc bns_common.processStdCdReq 는 Gauce(DataID/trsObj.Post) 잔재 — 업무공통 전환 후 시그니처 재대조
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.btn_StdCdReq_onclick" });
    }
};

