/**
 * @method
 * @name btn_TeamleadrConfrm_onclick
 * @description 「팀장확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_TeamleadrConfrm_onclick = async function () {
    try {
        if (scwin.vRowCount === 0) return;
        scwin.processGp = "6";
        scwin.vRowPos = dlt_searchList.getRowPosition(); // 팀장확인만 RowPosition setting 누락 수정 jackal_140319

        // 종목정보체크
        if (await $c.bns.checkNewListIsuInfoWIT(dma_bndIsu) > 0) return; // 업무공통 확인필요
        let confrmDd = dlt_searchList.getCellData(dlt_searchList.getRowPosition(), "teamleaderConfrmDd");
        $c.bns.teamleadrConfrm1(scwin.screnId, trs_Save, confrmDd, scwin.vBndApplId, scwin.vBndListProcsTpCd); // 업무공통 확인필요
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.btn_TeamleadrConfrm_onclick" });
    }
};

/**
 * @method
