    if (scwin.vRowCount === 0) return;
    try {
        scwin.processGp = '4';
        scwin.vRowPos = dlt_searchList.getRowPosition();
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS00100.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name btn_Acpt_onclick
 * @description 「접수」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function () {
    try {
        if (scwin.vRowCount === 0) return;
        scwin.processGp = '1';
        scwin.vRowPos = scwin.vBndApplId;
        await scwin.acpt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.btn_Acpt_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description 저장 트랜잭션 실패 후처리(레거시 Gauce 이벤트) — 처리구분별 실패 알림
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function () {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "접수"));
        }
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
        }
        if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
        }
        if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
        }
        if (scwin.processGp === '9') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "표준코드요청"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description 저장 트랜잭션 성공 후처리(레거시 Gauce 이벤트) — 처리구분별 완료 알림 후 목록 재조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function () {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
        }
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "처리완료"));
            await scwin.listSync();
        }
        if (scwin.processGp === '4') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
            await scwin.listSync();
        }
        if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
            await scwin.listSync();
        }
        if (scwin.processGp === '9') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A001", "표준코드요청"));
        }

        // 접수
        if (scwin.processGp === '1') {
            // tab_List.ActiveIndex = 2;
            scwin.clearIsuInfo();
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.trs_Save_OnSuccess" });
    }
};

