/**
 * @method
 * @name cmb_IntPayMethdCd_onselchange2
 * @description 이자지급방법 콤보 선택 변경 처리(레거시 OnSelChange2 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_IntPayMethdCd_onselchange2 = function () {
    try {
        let cd = cmb_IntPayMethdCd.getValue();
        // 이자지급방법이 변동금리형이면
        if (cd > 20) {
            // 변동금리탭 설정
            cmb_IntRtDecsnMiscBasIntCd.setDisabled(false);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
            cmb_IntRtDecsnMiscBasIntCd.setValue(cmb_CoupnRtDecsnBasIntCd.getValue());
            if (cmb_CoupnRtDecsnBasIntCd.getValue() === '90') {
                txb_CoupnRtMiscBasIntContn.setDisabled(false);
                txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
                if (!$c.util.isEmpty(txb_IntRtDecsnMiscBasIntNm.getValue()) && $c.util.isEmpty(txb_CoupnRtMiscBasIntContn.getValue())) {
                    txb_CoupnRtMiscBasIntContn.setValue(txb_IntRtDecsnMiscBasIntNm.getValue());
                } else {
                    txb_IntRtDecsnMiscBasIntNm.setValue(txb_CoupnRtMiscBasIntContn.getValue());
                }
            } else {
                txb_IntRtDecsnMiscBasIntNm.setValue('');
                txb_CoupnRtMiscBasIntContn.setValue('');
                txb_CoupnRtMiscBasIntContn.setDisabled(true);
                txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
            }
        } else {
            // 변동금리탭 클리어
            cmb_IntRtDecsnMiscBasIntCd.setValue('');
            txb_IntRtDecsnMiscBasIntNm.setValue('');
            cmb_SpdSgn.setValue('');
            edt_Spd.setValue('');
            cmb_IntRtDecsnTmCd.setValue('');
            edt_UplmtCoupnRt.setValue('');
            edt_LwlmtCoupnRt.setValue('');
            edt_IntRtDecsnBasDd.setValue('');
            dlt_bndChgInt.removeAll();
            cmb_IntRtDecsnMiscBasIntCd.setDisabled(true);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
            // txb_CoupnRtMiscBasIntContn.disabled = true;

            // 변동금리 추가항목 클리어 JACKAL_190509
            cmb_IntDecsnRegulYn.setValue('');
            txb_IntDecsnNregulRsnContn.setValue('');
            cmb_IntDecsnBasTpCd.setValue('');
            edt_IntDecsnBasDys.setValue('');
            edt_IntPayCnt.setValue('');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS00100.cmb_IntPayMethdCd_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_CoupnRtDecsnBasIntCd_onkillfocus
 * @description cmb_CoupnRtDecsnBasIntCd onkillfocus 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_CoupnRtDecsnBasIntCd_onkillfocus = function () {
    try {
        // 이자지급방법이 변동금리형
        let cd = cmb_IntPayMethdCd.getValue();
        if (cd > 20) {
            // 변동금리탭
            cmb_IntRtDecsnMiscBasIntCd.setDisabled(false);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
            cmb_IntRtDecsnMiscBasIntCd.setValue(cmb_CoupnRtDecsnBasIntCd.getValue());
            // 기타를 선택하면
            if (cmb_CoupnRtDecsnBasIntCd.getValue() === '90') {
                txb_CoupnRtMiscBasIntContn.setDisabled(false);
                txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
            } else {
                txb_CoupnRtMiscBasIntContn.setDisabled(true);
                txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
                txb_CoupnRtMiscBasIntContn.setValue('');
                txb_IntRtDecsnMiscBasIntNm.setValue('');
            }
        } else {
            if (cmb_CoupnRtDecsnBasIntCd.getValue() === '90') {
                txb_CoupnRtMiscBasIntContn.setDisabled(false);
            } else {
                txb_CoupnRtMiscBasIntContn.setDisabled(true);
                txb_CoupnRtMiscBasIntContn.setValue('');
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS00100.cmb_CoupnRtDecsnBasIntCd_onkillfocus" });
    }
};

