                txb_CoupnRtMiscBasIntContn.setDisabled(true);
                txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS00100.cmb_IntRtDecsnMiscBasIntCd_onkillfocus" });
    }
};

/**
 * @method
 * @name tab_Detail_onselchanged
 * @description tab_Detail onselchanged 이벤트
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_Detail_onselchanged = function (nIndex) {
    try {
        if (scwin.vRowCount === 0) return;
        if (cmb_IntPayMethdCd.getValue() > 20) {
            // 표면이자율선택시 변동금리의 기타 설정
            if (nIndex === 3) {
                if (cmb_IntRtDecsnMiscBasIntCd.getValue() === '90') {
                    txb_CoupnRtMiscBasIntContn.setValue(txb_IntRtDecsnMiscBasIntNm.getValue());
                }
            }
            // 변동금리선택시 표면이자율의 기타 설정
            else if (nIndex === 4) {
                if (cmb_CoupnRtDecsnBasIntCd.getValue() === '90') {
                    txb_IntRtDecsnMiscBasIntNm.setValue(txb_CoupnRtMiscBasIntContn.getValue());
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS00100.tab_Detail_onselchanged" });
    }
};

