/**
 * @method
 * @name dlt_frnBasIntTpCd4_OnFilter
 * @description 기준금리상세4 콤보 데이터 필터 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row row
 * @returns {Boolean}
 * @hidden N
 */
scwin.dlt_frnBasIntTpCd4_OnFilter = function (row) {
    try {
        let frnBasIntTpCd1 = cmb_FrnBasIntTpCd1.getValue();
        if (frnBasIntTpCd1 === "1" || frnBasIntTpCd1 === "6" || frnBasIntTpCd1 === "7") {
            return false;
        } else if (frnBasIntTpCd1 === "2" || frnBasIntTpCd1 === "3" || frnBasIntTpCd1 === "4") {
            if (dlt_frnBasIntTpCd4.getCellData(row, "value").substr(0, 1) === "0") {
                return true;
            } else {
                return false;
            }
        } else if (frnBasIntTpCd1 === "5") {
            if (dlt_frnBasIntTpCd4.getCellData(row, "value").substr(0, 1) === frnBasIntTpCd1) {
                return true;
            } else {
                return false;
            }
        } else {
            return false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS00100.dlt_frnBasIntTpCd4_OnFilter" });
    }
};

