 */
scwin.tab_List_ontabclick = async function (tabId, index) {
    try {
        scwin.vRowCount = 0;
        scwin.clearIsuInfo();
        scwin.vBndListProcsTpCd = String(index + 1);
        txb_Dtl1.hide();
        txb_Dtl.show('');
