            txb_Dtl.setValue("접수내역");
            btn_Search2.show();
            btn_ApprovFileCreat.show();
            btn_ProcsComplt.show();
            btn_Update.show();
            btn_TeamleadrConfrm.show();
            btn_AcptRet.show();

            btn_Search.hide();
            btn_Acpt.hide();
            btn_ApplRet.hide();
        } else {
            txb_Dtl.setValue("신청내역");
            btn_Search.show();
            btn_Acpt.show();
            btn_ApplRet.show();

            btn_Search2.hide();
            btn_ApprovFileCreat.hide();
            btn_ProcsComplt.hide();
            btn_Update.hide();
            btn_TeamleadrConfrm.hide();
            btn_AcptRet.hide();
        }
        scwin.chgStatComp();
        //  국채인 경우만 발행전국채거래구분코드 수정가능  jackal_150127
        scwin.presaleGovbndTrdTpCd();
        await scwin.listSync();
        scwin.setDtlTab();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS00100.tab_List_ontabclick" });
    }
};

