/**
 * @method
 * @name listSync
 * @description 신청/접수 목록을 조회한다.
 * @param {Number} rowIndex rowIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function (rowIndex) {
    if (rowIndex === "" || rowIndex === undefined) {
        rowIndex = 0;
    }
    scwin.vRowPos = rowIndex;
    dma_search.set("vMktactCd", scwin.vMktactCd); // 시장조치코드
    dma_search.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd); // 채권처리구분(1:신청,2:접수)

    const sbmOptions = {
        id: "sbm_searchList",
        action: "/api/bonds/bndNew/WITSymAssign/WITSymAssignApplAcpt-select",
        method: "get",
        ref: "dma_search=body",
        target: "dlt_searchList=body",
        gridview: "grd_ApplList,grd_AcptList",
        isProcessMsg: false
        // submitDoneHandler: scwin.sbm_searchList_submitdone,
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_searchList_submitdone(res);

    if (scwin.vBndListProcsTpCd === '1') {
        grd_ApplList.show('');
    } else {
        grd_AcptList.show('');
    }
};

/**
 * @method
 * @name sbm_searchList_submitdone
 * @description searchList 통신 후처리
 * @param {Object} e e
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_searchList_submitdone = async function (e) {
    if (e.responseStatusCode === 200) {
        if (scwin.vBndListProcsTpCd === '1' || scwin.vBndListProcsTpCd === '2') {
            scwin.rowPos(dlt_searchList, scwin.vRowPos);
        }

        let row = dlt_searchList.getRowPosition();
        if (row > -1) {
            scwin.vBndApplId = dlt_searchList.getCellData(row, "bndApplId");
            scwin.vProcsStatCd = dlt_searchList.getCellData(row, "procsStatCd");
            await scwin.dtlSync();
        }

        if (scwin.vBndListProcsTpCd === '1') {
            grd_ApplList.setFocusedCell(scwin.vRowPos, "bndApplId", false);
        } else {
            grd_AcptList.setFocusedCell(scwin.vRowPos, "bndApplId", false);
            for (let i = 0; i < dlt_searchList.getRowCount(); i++) {
                if (dlt_searchList.getDataRow(i).procsStat === '처리완료' &&
                    (dlt_searchList.getDataRow(i).teamleaderConfrmDd !== "undefined" && dlt_searchList.getDataRow(i).teamleaderConfrmDd !== '-' && dlt_searchList.getDataRow(i).teamleaderConfrmDd !== '')) { // 처리완료만 팀장확인 대상임
                    grd_AcptList.setCellDisabled(i, "CHK", true);
                }
            }
        }

    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
}

/**
 * @method
 * @name dtlSync
 * @description 그리드 선택 시 상세내역을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dtlSync = async function () {
    dma_search.set('vBndApplId', scwin.vBndApplId); // 채권신청ID
    dma_search.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd); // 채권처리구분(1:신청,2:접수)

    const sbmOptions = {
        id: "sbm_detail",
        action: "/api/bonds/bndNew/WITSymAssign/WITSymAssignDetail-select",
        method: "get",
        ref: "dma_search=body",
        target: "dma_bndIsu=body.bndIsu,dlt_bndCredit=body.bndCredit,dlt_bndSplitRedmpt=body.bndCredit,dlt_bndUdwrtInst=body.bndUdwrtInst,dma_bndCoupnRtAndIsurPrc=body.bndCoupnrtIsurprc,dlt_bndPrincintInfo=body.bndPrincintInfo,dlt_bndOptionCall=body.bndOptionCall,dlt_bndOptionPut=body.bndOptionPut,dlt_bndChgInt=body.bndChgInt,dlt_bndSecutizAsst=body.bndSecutizAsst,dlt_bndStockRelExecprcAdj=body.bndStockRelExecprcAdj",
        // gridview: "grd_ApplList,grd_AcptList",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_detail_submitdone(sbmRtn);
};

/**
 * @method
 * @name sbm_detail_submitdone
 * @description detail 통신 후처리
 * @param {Object} e e
 * @returns {void}
 * @hidden N
 */
scwin.sbm_detail_submitdone = function (e) {
    if (e.responseStatusCode === 200) {
        scwin.vRowCount = dma_bndIsu.getCount();

        // 버튼설정
        scwin.setBtn();

        // 물가연동채구분
        if (dma_bndIsu.get('isurCd') === 'GB035') {
            cmb_InfllnkYn.setDisabled(false);
            edt_IsuDdRefIdx.setDisabled(false);
        } else {
            cmb_InfllnkYn.setDisabled(true);
            edt_IsuDdRefIdx.setDisabled(true);
        }

        // 한글금액표기
        txb_AmtHan.setValue($c.num.numberToKor(dma_bndIsu.get('listAmt'), "원"));

        // 금액여분적용
        // scwin.setMargin();

        if (scwin.vRowCount === -1) return;
        let lbl = "";
        if (!$c.util.isEmpty(dma_bndIsu.get('stdCd'))) {
            let isuNm = dma_bndIsu.get('stdRefDtl');
            lbl = "신청내역" + isuNm;
            txb_Dtl1.setValue(lbl);
            txb_Dtl.hide();
            txb_Dtl1.show('');
        } else {
            txb_Dtl1.hide();
            txb_Dtl.show('');
        }

        // 신용등급 SF
        if (scwin.vBndListProcsTpCd !== '1' &&
            $c.util.isEmpty(cmb_AsstSecutizTpCd.getValue())) {
            cmb_SfValuYn1.setValue('');
            cmb_SfValuYn2.setValue('');
            cmb_SfValuYn3.setValue('');
            cmb_SfValuYn4.setValue('');
            cmb_SfValuYn1.setDisabled(true);
            cmb_SfValuYn2.setDisabled(true);
            cmb_SfValuYn3.setDisabled(true);
            cmb_SfValuYn4.setDisabled(true);
        }

        // 기준금리상세1의 값에다른 항목 활성/비활성 등 제어.
        // 콤보 활성비활성, 보이고 안보이고 세팅
        if (tab_List.getSelectedTabIndex() === 1) {
            scwin.ctrlObject11();
        } else {
            scwin.ctrlObject12();
        }

        // dlt_bndSecutizAsst 후 처리
        let rowcount = dlt_bndSecutizAsst.getRowCount();
        cmb_SecutizAsstTpCd1.setValue('0');
        cmb_AsstHdTpCd1.setValue('0');
        cmb_AsstHdInstCd1.setValue('0');
        cmb_AsstAdmInstCd1.setValue('0');
        cmb_SecutizAsstTpCd2.setValue('0');
        cmb_AsstHdTpCd2.setValue('0');
        cmb_AsstHdInstCd2.setValue('0');
        cmb_AsstAdmInstCd2.setValue('0');
        cmb_SecutizAsstTpCd3.setValue('0');
        cmb_AsstHdTpCd3.setValue('0');
        cmb_AsstHdInstCd3.setValue('0');
        cmb_AsstAdmInstCd3.setValue('0');
        txb_AsstHdInstMiscContn.setValue('');
        txb_AsstHdTpMiscContn.setValue('');
        txb_AsstAdmInstMiscContn.setValue('');
        txb_SecutizAsstTpMiscContn.setValue('');
        txb_AsstHdInstMiscContn.setValue('');
        if (rowcount > 0) {
            for (let idx = 0; idx < rowcount; idx++) {
                if (dlt_bndSecutizAsst.getCellData(idx, 'hdAsstOrd') === '1') {
                    scwin.setSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd1);
                    scwin.setSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd1, cmb_AsstHdInstCd1, cmb_AsstAdmInstCd1);
                } else if (dlt_bndSecutizAsst.getCellData(idx, 'hdAsstOrd') === '2') {
                    scwin.setSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd2);
                    scwin.setSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd2, cmb_AsstHdInstCd2, cmb_AsstAdmInstCd2);
                } else if (dlt_bndSecutizAsst.getCellData(idx, 'hdAsstOrd') === '3') {
                    scwin.setSecutizAsstTpCd(idx, cmb_SecutizAsstTpCd3);
                    scwin.setSecutizAsstHdTpCd(idx, cmb_AsstHdTpCd3, cmb_AsstHdInstCd3, cmb_AsstAdmInstCd3);
                } else if (dlt_bndSecutizAsst.getCellData(idx, 'hdAsstOrd') === '4') {
                    txb_SecutizAsstTpMiscContn.setValue(dlt_bndSecutizAsst.getCellData(idx, 'secutizAsstTpMiscContn'));
                    txb_AsstHdTpMiscContn.setValue(dlt_bndSecutizAsst.getCellData(idx, 'asstHdTpMiscContn'));
                    txb_AsstHdInstMiscContn.setValue(dlt_bndSecutizAsst.getCellData(idx, 'asstHdInstMiscContn'));
                    txb_AsstAdmInstMiscContn.setValue(dlt_bndSecutizAsst.getCellData(idx, 'asstAdmInstMiscContn'));
                }
            }
        }
        // dlt_bndCredit 후 처리
        rowcount = dlt_bndCredit.getRowCount();
        cmb_CreditValuInstCd1.setValue('0');
        cmb_ByinstCreditValuGrd1.setValue('0');
        cmb_SfValuYn1.setValue('');
        cmb_CreditValuInstCd2.setValue('0');
        cmb_ByinstCreditValuGrd2.setValue('0');
        cmb_SfValuYn2.setValue('');
        cmb_CreditValuInstCd3.setValue('0');
        cmb_ByinstCreditValuGrd3.setValue('0');
        cmb_SfValuYn3.setValue('');
        cmb_CreditValuInstCd4.setValue('0');
        cmb_ByinstCreditValuGrd4.setValue('0');
        cmb_SfValuYn4.setValue('');
        if (rowcount > 0) {
            for (let idx = 0; idx < rowcount; idx++) {
                if (dlt_bndCredit.getCellData(idx, 'creditValuInstCd') === '9201') {
                    cmb_CreditValuInstCd1.setValue(dlt_bndCredit.getCellData(idx, "creditValuInstCd"));
                    cmb_ByinstCreditValuGrd1.setValue(dlt_bndCredit.getCellData(idx, "byinstCreditValuGrd"));
                    cmb_SfValuYn1.setValue(dlt_bndCredit.getCellData(idx, "sfValuYn"));
                } else if (dlt_bndCredit.getCellData(idx, 'creditValuInstCd') === '9202') {
                    cmb_CreditValuInstCd2.setValue(dlt_bndCredit.getCellData(idx, "creditValuInstCd"));
                    cmb_ByinstCreditValuGrd2.setValue(dlt_bndCredit.getCellData(idx, "byinstCreditValuGrd"));
                    cmb_SfValuYn2.setValue(dlt_bndCredit.getCellData(idx, "sfValuYn"));
                } else if (dlt_bndCredit.getCellData(idx, 'creditValuInstCd') === '9203') {
                    cmb_CreditValuInstCd3.setValue(dlt_bndCredit.getCellData(idx, "creditValuInstCd"));
                    cmb_ByinstCreditValuGrd3.setValue(dlt_bndCredit.getCellData(idx, "byinstCreditValuGrd"));
                    cmb_SfValuYn3.setValue(dlt_bndCredit.getCellData(idx, "sfValuYn"));
                } else if (dlt_bndCredit.getCellData(idx, 'creditValuInstCd') === '9204') {
                    cmb_CreditValuInstCd4.setValue(dlt_bndCredit.getCellData(idx, "creditValuInstCd"));
                    cmb_ByinstCreditValuGrd4.setValue(dlt_bndCredit.getCellData(idx, "byinstCreditValuGrd"));
                    cmb_SfValuYn4.setValue(dlt_bndCredit.getCellData(idx, "sfValuYn"));
                }
            }
        }

        // dlt_bndUdwrtInst 후 처리
        rowcount = dlt_bndUdwrtInst.getRowCount();
        cmb_BndUdwrtInstCd1.setValue('0');
        edt_UdwrtAmt1.setValue('');
        cmb_BndUdwrtInstCd2.setValue('0');
        edt_UdwrtAmt2.setValue('');
        cmb_BndUdwrtInstCd3.setValue('0');
        edt_UdwrtAmt3.setValue('');
        cmb_BndUdwrtInstCd4.setValue('0');
        edt_UdwrtAmt4.setValue('');
        edt_UdwrtAmt5.setValue('');
        if (rowcount >= 1) {
            scwin.setUdwrtInst(1, cmb_BndUdwrtInstCd1, edt_UdwrtAmt1);
        }
        if (rowcount >= 2) {
            scwin.setUdwrtInst(2, cmb_BndUdwrtInstCd2, edt_UdwrtAmt2);
        }
        if (rowcount >= 3) {
            scwin.setUdwrtInst(3, cmb_BndUdwrtInstCd3, edt_UdwrtAmt3);
        }
        if (rowcount >= 4) {
            scwin.setUdwrtInst(4, cmb_BndUdwrtInstCd4, edt_UdwrtAmt4);
        }
        if (rowcount >= 5) {
            edt_UdwrtAmt5.setValue(dlt_bndUdwrtInst.getCellData(5, 'UDWRT_AMT'));
        }
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
};

