    let vIntPayUnitMms = edt_IntPayUnitMms.getValue();
    let vIntMmendTpCd = cmb_IntMmendTpCd.getValue();
    let vIntPayCnt = edt_IntPayCnt.getValue();
    let vIntDecsnBasDys = edt_IntDecsnBasDys.getValue();
