    dma_bndAutoCreate.set('vIsuDd', vIsuDd); // 발행일
    dma_bndAutoCreate.set('vFstIntPayDd', vFstIntPayDd); // 최초이자지급일
    dma_bndAutoCreate.set('vIntPayUnitMms', vIntPayUnitMms); // 이자지급주기
    dma_bndAutoCreate.set('vIntMmendTpCd', vIntMmendTpCd); // 이자월말구분코드
