/**
 * @method
 * @name acpt
 * @description 신청데이터를 접수 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.acpt = async function () {
    // 종목정보체크
    if (await $c.bns.checkNewListIsuInfo(dma_bndIsu) > 0) return;
    if (await scwin.checkEach() > 0) return;
    // 적용일,매매일,마감일,채권마감 체크
    if (await scwin.checkCmData(dma_CheckCmData, edt_StrtDd.getValue(), scwin.vBndApplId) > 0) return;
    // 채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if (await $c.bns.chkBndClssAndIsur1(scwin.screnId, dma_bndIsu, scwin.vMktactCd) > 0) return;

    // 고객요건에의한 체크 추가. 2024-06-05 by김효준
    if (await $c.bns.addCheck(dma_bndIsu) > 0) return;

    // 접수
    // let hasAttachDoc = dma_bndIsu.get("hasAttachDoc");
    // if(! fn_EndConfirm(hasAttachDoc, '접수')) return;
    if (! await $c.bns.endConfirm1(scwin.screnId, dma_bndIsu, scwin.vBndApplId, scwin.vBndListProcsTpCd, '접수')) return;

    // TODO == 수수료팝업 작업 전으로 임시데이터 넣음
    scwin.getParNewListFee();
    // const url = "/ui/bns/bnslistbzappl/ULDBNS20002.xml";

    // const options = {
    //     id: "ULDBNS25001",
    //     popupName: "발행기관 검색",
    //     frameModal: "top",
    //     width: 600,
    //     height: 500,
    // };

    // let rtn = await $c.win.openPopup(url, options, scwin.arrPar);

    // scwin.setParNewListFee(rtn);

    // if (scwin.vRegYn != "Y") return;

    // 수수료 팝업 작업 전으로 임시데이터 넣는 부분
    dma_newListFee.set('bndApplId', scwin.vBndApplId);
    dma_newListFee.set('bndListProcsTpCd', scwin.vBndListProcsTpCd);
    dma_newListFee.set('feeGrpNm', 'test');
    // 여기까지

    // 변경된 데이터가 없더라도 데이터셋 전송하여 처리 진행
    // dts_Fee.UseChangeInfo = "False";

    dma_Param.set('bndApplId', scwin.vBndApplId);
    dma_Param.set('bndListProcsTpCd', scwin.vBndListProcsTpCd);
    dma_Param.set('strtDd', dma_bndIsu.get("strtDd"));
    dma_bndIsu.set('coupnRtDecsnBasIntCd', cmb_CoupnRtDecsnBasIntCd.getValue());

    const sbmOptions = {
        id: "sbm_acptList",
        action: "/api/bonds/bndNew/WITSymAssign/WITSymAssignAppl-proc",
        method: "post",
        ref: "dma_Param=dts_Param,dma_bndIsu=dts_IsuInfo,dma_newListFee=dts_NewListFee",
        // target: "dlt_searchList=body",
        // gridview: "grd_List1,grd_List2",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_acptList_submitdone(sbmRtn);
};

