/**
 * @method
 * @name setMktactCd
 * @description 신규상장 채권시장조치구분코드를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setMktactCd = function () {
    // 숨기기
    label_47.hide();
    cmb_MunibndTpCd.hide();

    let frameP = null;
    if (typeof frame === "object") {
        frameP = frame.$p;
    } else {
        frameP = $p;
    }
    let screenId = $c.win.getProgramId(frameP);

    // 국채 WIT 지정 jackal_15.09.17
    if (screenId === "ULDBNS00100") {
        scwin.vMktactCd = "113";
        cmb_BndTpCd.setValue('GB');
        cmb_BndTpCd.setDisabled(true);
        cmb_PresaleGovbndTrdTpCd.setValue('1');
        cmb_PresaleGovbndTrdTpCd.setDisabled(true);
        cmb_CoupnRtFinalYn.setValue('N');
        cmb_CoupnRtFinalYn.setDisabled(true);
        edt_CoupnRt.setValue(0);
        // edt_CoupnRt.Enable2 = false;
    }
    // 국채 개별상장
    else if (screenId === "ULDBNS00000") {
        scwin.vMktactCd = "111";
        cmb_BndTpCd.setValue('GB');
        cmb_BndTpCd.setDisabled(true);
    }
    // 지방채
    else if (screenId === "ULDBNS01000") {
        scwin.vMktactCd = "121";
        label_47.show('');
        cmb_MunibndTpCd.show('');
        cmb_BndTpCd.setValue('MB');
        cmb_BndTpCd.setDisabled(true);
    }
    // 특수채 개별상장
    else if (screenId === "ULDBNS02000") {
        scwin.vMktactCd = "131";
        cmb_BndTpCd.setValue('AB');
        cmb_BndTpCd.setDisabled(true);
    }
    // 회사채 개별상장
    else if (screenId === "ULDBNS03000") {
        scwin.vMktactCd = "141";
        cmb_BndTpCd.setValue('CO');
        cmb_BndTpCd.setDisabled(true);
    }
    // 외국채권 개별상장
    else if (screenId === "ULDBNS04000") {
        scwin.vMktactCd = "151";
        cmb_BndTpCd.setValue('FO');
        cmb_BndTpCd.setDisabled(true);
    }
};

