/**
 * @method
 * @name minusGumriOK
 * @description 개별 체크한다. (JACKAL_191129)
 * @param {Object} obj obj
 * @param {String} msg msg
 * @returns {Promise<Number>}
 * @hidden N
 */
scwin.minusGumriOK = async function (obj, msg) {
    let obj_rt = obj.getValue();

    if (obj_rt < 0) {
        if (! await $c.win.confirm('[' + msg + '] 마이너스(-) 값을 입력하셨습니다.<br/>이대로 처리하시겠습니까?')) {
            // setObjectValue(obj, obj_rt*(-1));
            obj.focus();
            return 1;
        }
    }
};

/**
 * @method
 * @name minusGumriCheck
 * @description 개별 체크한다. (JACKAL_191129 / edt_CoupnRt COUPN_RT / edt_ScbdInt SCBD_INT / edt_BkHoldyDdPrincAcrintRt BK_HOLDY_DD_PRINC_ACRINT_RT / edt_BkHoldyDdIntCmpAcrintRt   BK_HOLDY_DD_INT_CMP_ACRINT_RT / edt_GrtYd GRT_YD / edt_AddYd ADD_YD)
 * @returns {Promise<Number>}
 * @hidden N
 */
scwin.minusGumriCheck = async function () {
    if (!await scwin.minusGumriOK(edt_CoupnRt, '표면이자율') &&
        !await scwin.minusGumriOK(edt_ScbdInt, '낙찰금리') &&
        !await scwin.minusGumriOK(edt_BkHoldyDdPrincAcrintRt, '휴무(원금)경과금리') &&
        !await scwin.minusGumriOK(edt_BkHoldyDdIntCmpAcrintRt, '휴무(이자)경과금리') &&
        !await scwin.minusGumriOK(edt_GrtYd, '보장수익률') &&
        !await scwin.minusGumriOK(edt_AddYd, '추가수익률')) return 1;

    else return 0;
};

/**
 * @method
 * @name checkFee
 * @description 신규,변경상장 수수료를 체크한다.
 * @param {String} eachGp eachGp
 * @param {Object} dtsObj dtsObj
 * @param {String} bndApplId bndApplId
 * @returns {Promise<Number>}
 * @hidden N
 */
scwin.checkFee = async function (eachGp, dtsObj, bndApplId) {
        await scwin.getCheckUrl('', bndApplId, 'N');

    if (eachGp === "1") {
        if (dma_rtnGetCheckUrl.get("VALID_FEE_NEW") === "Y") {
            await $c.win.alert("수수료그룹지정이 안된종목입니다. 수수료그룹지정을 하십시오!"); return 5;
        }
    } else if (eachGp === "2") {
        if (dma_rtnGetCheckUrl.get("VALID_FEE_CHG") === "Y") {
            await $c.win.alert("수수료그룹지정이 안된종목입니다. 수수료그룹지정을 하십시오!"); return 5;
        }
    }

    return 0;
}

