/**
 * @method
 * @name checkCmData
 * @description 월별 접수,처리완료,수정 시 체크항목
 * @param {Object} dtsObj dtsObj
 * @param {String} strtDd strtDd
 * @param {String} bndApplId bndApplId
 * @returns {Promise<Number>}
 * @hidden N
 */
scwin.checkCmData = async function (dtsObj, strtDd, bndApplId) {
    await scwin.getCheckUrl(strtDd, bndApplId, 'N');

    if (dma_rtnGetCheckUrl.get("VALID_STRT_DD") === "Y") {
        await $c.win.alert("적용일이 현재일자보다 작습니다. 다시 입력하십시오.");
        return 1;
    }
    if (dma_rtnGetCheckUrl.get("VALID_CALND_DD") === "Y") {
        await $c.win.alert("적용일이 매매일에 유효하지 않습니다. 다시 입력하십시오.");
        return 2;
    }
    // 추가-적용일 전날이 아니면 확인메시지 보여주기
    if (dma_rtnGetCheckUrl.get("VALID_BF_DD") === "Y") {
        if (! await $c.win.confirm("상장일/적용일이 익영업일이 아닙니다. 처리하시겠습니까?")) {
            return 4;
        }
    }
    if (dma_rtnGetCheckUrl.get("VALID_CLS_DD") === "Y") {
        $c.win.alert("입력한 일자는 이미 마감처리가 종료된 일자입니다. 다시 입력하십시오."); {
            return 3;
        }
    }

    return 0;
}

