 * @method
 * @name showIsur
 * @description 발행기관 팝업을 보여준다.
 * @param {*} selObj selObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showIsur = async function (selObj) {

    scwin.vSelObj = selObj;
    scwin.getParIsurCd();
    const url = "/ui/bns/bnslistsrchl/ULDBNS25001.xml";

    const options = {
        id: "ULDBNS25001",
        popupName: "발행기관 검색",
        frameModal: "top",
        width: 600,
        height: 500,
    };
    let rtn = await $c.win.openPopup(url, options, scwin.arrPar);
    scwin.setParIsurCd(rtn);
};

/**
 * @method
 * @name showInst
 * @description 기관 팝업을 보여준다.
 * @param {*} selObj selObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showInst = async function (selObj) {

    scwin.vSelObj = selObj;
    scwin.getParInst();
    const url = "/ui/bns/bnslistbzappl/ULDBNS21102.xml";
    const options = {
        id: "ULDBNS21102",
        popupName: "기관 검색",
        frameModal: "top",
        width: 600,
        height: 500,
    };
    const rtn = await $c.win.openPopup(url, options, scwin.arrPar);
    scwin.setParInst(rtn);
};

