    return scwin.arrPar;
};

/**
 * @method
 * @name setUdwrtInst
 * @description 인수기관 데이터를 설정한다.
 * @param {*} rowIdx rowIdx
 * @param {*} cbObj cbObj
 * @param {*} edtObj edtObj
 * @returns {void}
 * @hidden N
 */
scwin.setUdwrtInst = function (rowIdx, cbObj, edtObj) {
    let UDWRT_INST_CD = dlt_bndUdwrtInst.getCellData(rowIdx, 'udwrtInstCd');
    if (UDWRT_INST_CD === '9999') {
        edt_UdwrtAmt5.setValue(dlt_bndUdwrtInst.getCellData(rowIdx, 'udwrtAmt'));
    } else {
        cbObj.setValue(dlt_bndUdwrtInst.getCellData(rowIdx, 'udwrtInstCd'));
        edtObj.setValue(dlt_bndUdwrtInst.getCellData(rowIdx, 'udwrtAmt'));
    }
};

