/**
 * @method
 * @name setSecutizAsstHdTpCd
 * @description 자산보유자 설정한다.
 * @param {*} rowIdx rowIdx
 * @param {*} cbHdTpObj cbHdTpObj
 * @param {*} cbHdInstObj cbHdInstObj
 * @param {*} cbAdmObj cbAdmObj
 * @returns {void}
 * @hidden N
 */
scwin.setSecutizAsstHdTpCd = function (rowIdx, cbHdTpObj, cbHdInstObj, cbAdmObj) {
    // 자산보유자유형
    cbHdTpObj.setValue(dlt_bndSecutizAsst.getCellData(rowIdx, 'asstHdTpCd'));
    txb_AsstHdTpMiscContn.setValue(dlt_bndSecutizAsst.getCellData(rowIdx, 'asstHdTpMiscContn'));

    // 자산보유자기관
    let cbdata = '';
    cbdata = "^ ," + dlt_bndSecutizAsst.getCellData(rowIdx, 'asstHdInstCd') + "^" + dlt_bndSecutizAsst.getCellData(rowIdx, 'asstHdInstNm');
    // cbHdInstObj.CBData = cbdata;
    cbHdInstObj.setValue(dlt_bndSecutizAsst.getCellData(rowIdx, 'asstHdInstCd'));
    txb_AsstHdInstMiscContn.setValue(dlt_bndSecutizAsst.getCellData(rowIdx, 'asstHdInstMiscContn'));

    // 자산관리자기관
    cbdata = "^ ," + dlt_bndSecutizAsst.getCellData(rowIdx, 'asstAdmInstCd') + "^" + dlt_bndSecutizAsst.getCellData(rowIdx, 'asstAdmInstNm');
    // cbAdmObj.CBData = cbdata;
    cbAdmObj.setValue(dlt_bndSecutizAsst.getCellData(rowIdx, 'asstAdmInstCd'));
    txb_AsstAdmInstMiscContn.setValue(dlt_bndSecutizAsst.getCellData(rowIdx, 'asstAdmInstMiscContn'));
};

/**
 * @method
 * @name setBtn
 * @description 버튼보이기를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setBtn = function () {
    if (scwin.vBndListProcsTpCd === '1') {
        btn_StdCdReq.hide();
        return;
    }
    if (txb_StdCd.getValue() === '') {
        btn_StdCdReq.show('');
        // btn_ProcsComplt.src = '../img/bns/btn_20_d.gif';
        btn_ProcsComplt.setDisabled(true);
        // btn_TeamleadrConfrm.src = '../img/bns/btn_21_d.gif';
        btn_TeamleadrConfrm.setDisabled(true);
    } else {
        btn_StdCdReq.hide();
        if (scwin.vProcsStatCd === "2") {
            // btn_ProcsComplt.src = '../img/bns/btn_20_d.gif';
            btn_ProcsComplt.setDisabled(true);
            // btn_TeamleadrConfrm.src = '../img/bns/btn_21.gif';
            btn_TeamleadrConfrm.setDisabled(false);
        } else {
            // btn_ProcsComplt.src = '../img/bns/btn_20.gif';
            btn_ProcsComplt.setDisabled(false);
            // btn_TeamleadrConfrm.src = '../img/bns/btn_21_d.gif';
            btn_TeamleadrConfrm.setDisabled(true);
        }
    }
};

