/**
 * @method
 * @name chkInstAlert
 * @description 발행기관 상태가 정상인지 확인한다.
 * @param {*} selObj selObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkInstAlert = async function (selObj) {
    if (selObj.getValue() === '') return;
    if (await scwin.showInstAlert(dlt_listInstCdRes, $c.cp.getNameValueRow(dlt_listInstCdRes, "INST_CD", selObj.getValue())) > 0) {
        selObj.setValue('');
    }
};

/**
 * @method
 * @name showInstAlert
 * @description 정상이 아니면 확인메시지를 보여준다.
 * @param {Object} dtsObj dtsObj
 * @param {*} rowpos rowpos
 * @returns {Promise<Number>}
 * @hidden N
 */
scwin.showInstAlert = async function (dtsObj, rowpos) {
    if (dtsObj.getCellData(rowpos, 'instStatCd') !== "1") {
        $c.win.alert("기관상태가 정상인 기관만 선택 가능 합니다.\n선택을 원할 경우 기관관리화면에서 상태를 변경 후 선택이 가능합니다.");
        return 1;
    }
    return 0;
}

/**
 * @method
 * @name chkCall
 * @description CALL 시작/종료일체크
 * @returns {Number}
 * @hidden N
 */
scwin.chkCall = function () {
    for (let idx = 0; idx < dlt_bndOptionCall.getRowCount(); idx++) {
        if (dlt_bndOptionCall.getCellData(idx, 'callExerStrtDd').length !== 8) {
            $c.win.alert('행사개시일을 입력하세요');
            return 1;
        }
    }
    return 0;
};

/**
 * @method
 * @name chkPut
 * @description PUT 시작/종료일체크
 * @returns {Number}
 * @hidden N
 */
scwin.chkPut = function () {
    for (let idx = 0; idx < dlt_bndOptionPut.getRowCount(); idx++) {
        if (dlt_bndOptionPut.getCellData(idx, 'putExerStrtDd').length !== 8) {
            $c.win.alert('행사개시일을 입력하세요');
            return 1;
        }
    }
    return 0;
};

/**
 * @method
 * @name ctrlFrnBasIntTpCd1
 * @description 기준금리상세 첫번째 콤보 onChange
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ctrlFrnBasIntTpCd1 = async function () {
    // 콤보 데이터 필터링
    await scwin.filterComboValue();

    // 콤보 활성비활성, 보이고 안보이고 세팅
    if (tab_List.getSelectedTabIndex() === 1) {
        scwin.ctrlObject11();
    } else {
        scwin.ctrlObject12();
    }
};

/**
 * @method
 * @name ctrlFrnBasIntTpCd3
 * @description 기준금리상세 세번째 콤보 onChange - 기타상세 항목 활성/비활성
 * @returns {void}
 * @hidden N
 */
scwin.ctrlFrnBasIntTpCd3 = function () {
    let frnBasIntTpCd3 = cmb_FrnBasIntTpCd3.getValue();
    // 콤보3의 기타 -- 상세입력만 활성
    if (frnBasIntTpCd3 === "2Z" || frnBasIntTpCd3 === "3Z" || frnBasIntTpCd3 === "4Z" || frnBasIntTpCd3 === "5Z") {
        txb_FrnBasIntMisc.setDisabled(false);
    } else {
        txb_FrnBasIntMisc.setDisabled(true); // 기타는 기본값 비활성
    }
};

/**
 * @method
 * @name filterComboValue
 * @description 기준금리 2~4번째 콤보 필터링
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.filterComboValue = async function () {
    let frnBasIntTpCd1 = cmb_FrnBasIntTpCd1.getValue();
    // TODO Stage2: Gauce OnFilter 콜백(행 인자 없이 호출돼 필터 동작 없음) → dlt_frnBasIntTpCd2.setColumnFilter 재구현 필요 — scwin.dlt_frnBasIntTpCd2_OnFilter();
    // TODO Stage2: Gauce OnFilter 콜백(행 인자 없이 호출돼 필터 동작 없음) → dlt_frnBasIntTpCd3.setColumnFilter 재구현 필요 — scwin.dlt_frnBasIntTpCd3_OnFilter();
    // TODO Stage2: Gauce OnFilter 콜백(행 인자 없이 호출돼 필터 동작 없음) → dlt_frnBasIntTpCd4.setColumnFilter 재구현 필요 — scwin.dlt_frnBasIntTpCd4_OnFilter();

    // 관련 항목 기본값 세팅
    await cmb_FrnBasIntTpCd2.setSelectedIndex(0);
    await cmb_FrnBasIntTpCd3.setSelectedIndex(0);
    await cmb_FrnBasIntTpCd4.setSelectedIndex(0);
};

/**
 * @method
 * @name ctrlObject11
 * @description 신청내역 탭에서 기준금리상세 항목 컨트롤 신청내역 탭에서는 전부 비활성...
 * @returns {void}
 * @hidden N
 */
scwin.ctrlObject11 = function () {
    let frnBasIntTpCd1 = cmb_FrnBasIntTpCd1.getValue();

    // 일단 전부 활성화
    cmb_FrnBasIntTpCd2.setDisabled(true);
    cmb_FrnBasIntTpCd3.setDisabled(true);
    cmb_FrnBasIntTpCd4.setDisabled(true);
    txb_FrnBasIntMisc.setDisabled(true); // 기타 비활성

    cmb_FrnBasIntTpCd2.show('');
    grp_FrnBasIntTp2.hide();
    txb_FrnBasIntTp2.hide();
    img_isurCd.hide();

    // 시가평가수익률(발행기관), 콤보2 안보이고 발행기관입력팝업 보이고..
    if (frnBasIntTpCd1 === "4") {
        cmb_FrnBasIntTpCd2.hide();
        grp_FrnBasIntTp2.show('');
        // txb_FrnBasIntTp2.show('');
        // img_isurCd.show('');
    }
};

/**
 * @method
 * @name ctrlObject12
 * @description 접수내역 탭에서 기준금리상세 항목 컨트롤
 * @returns {void}
 * @hidden N
 */
scwin.ctrlObject12 = function () {
    let frnBasIntTpCd1 = cmb_FrnBasIntTpCd1.getValue();

    // 일단 전부 활성화
    cmb_FrnBasIntTpCd2.setDisabled(false);
    cmb_FrnBasIntTpCd3.setDisabled(false);
    cmb_FrnBasIntTpCd4.setDisabled(false);
    // txb_FrnBasIntMisc.disabled = true;  //기타는 비활성

    cmb_FrnBasIntTpCd2.show('');
    grp_FrnBasIntTp2.hide();
    // txb_FrnBasIntTp2.hide();
    // img_isurCd.hide();

    // 최종호가수익률
    if (frnBasIntTpCd1 === "1") {
        cmb_FrnBasIntTpCd4.setDisabled(true);

        // 시가평가수익률(CD/CP), 시가평가수익률(채권그룹), 워노하이자율스왑

    } else if (frnBasIntTpCd1 === "2" || frnBasIntTpCd1 === "3" || frnBasIntTpCd1 === "5") {
        // nothing to do

        // 시가평가수익률(발행기관), 콤보2 안보이고 발행기관입력팝업 보이고..

    } else if (frnBasIntTpCd1 === "4") {
        cmb_FrnBasIntTpCd2.hide();
        grp_FrnBasIntTp2.show('');
        // txb_FrnBasIntTp2.show('');
        // img_isurCd.show('');

        // KOFR금리 -- 전부 비활성

    } else if (frnBasIntTpCd1 === "6") {
        cmb_FrnBasIntTpCd2.setDisabled(true);
        cmb_FrnBasIntTpCd3.setDisabled(true);
        cmb_FrnBasIntTpCd4.setDisabled(true);

        // 기타 -- 상세입력빼고 전부 비활성

    } else if (frnBasIntTpCd1 === "7") {
        cmb_FrnBasIntTpCd2.setDisabled(true);
        cmb_FrnBasIntTpCd3.setDisabled(true);
        cmb_FrnBasIntTpCd4.setDisabled(true);
        txb_FrnBasIntMisc.setDisabled(false); // 상세입력만 활성

    }
};

/**
 * @method
 * @name showIsurPopup
 * @description 발행기관 팝업을 보여준다.
 * @param {Object} obj obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showIsurPopup = async function (obj) {
    scwin.getParFrnBasIntIsur();
    const url = "/ui/bns/bnslistsrchl/ULDBNS25001.xml";
    const options = {
        id: "ULDBNS25001",
        popupName: "발행기관 검색",
        frameModal: "top",
        width: 600,
        height: 500,
    };
    let rtn = await $c.win.openPopup(url, options, scwin.arrPar);
    scwin.setParFrnBasIntIsur(rtn);
};

/**
 * @method
 * @name getParFrnBasIntIsur
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar arrPar
 * @returns {Array}
 * @hidden N
 */
scwin.getParFrnBasIntIsur = function (arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: txb_FrnBasIntTpCd2.getValue(),
        ISUR_NM: txb_FrnBasIntTp2.getValue()
    };
    return scwin.arrPar;
};

/**
 * @method
 * @name setParFrnBasIntIsur
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar arrPar
 * @returns {void}
 * @hidden N
 */
scwin.setParFrnBasIntIsur = function (arrPar) {
    txb_FrnBasIntTpCd2.setValue(arrPar[0].ISUR_CD);
    txb_FrnBasIntTp2.setValue(arrPar[0].ISUR_NM);
};

