/**
 * @method
 * @name checkModAndRet
 * @description 접수 후 수정 및 반송시 체크한다.
 * @param {Object} dtsObj dtsObj
 * @param {String} bndApplId bndApplId
 * @returns {Promise<Number>}
 * @hidden N
 */
scwin.checkModAndRet = async function (dtsObj, bndApplId) {
    await scwin.getCheckUrl('', bndApplId, 'N');

    if (dma_rtnGetCheckUrl.get("VALID_BND") === "Y") {
        $c.win.alert("이미 마감처리가 된 종목입니다. 처리하실수 없습니다.");
        return 4;
    }

    return 0;
};
